def has_even_digit(n):
    while n > 0:
        if (n % 2 == 0) and (n % 10 != 0):
            return True
        n //= 10
    return False

def unique_digits(x):
    """Given a list of positive integers x. Return a sorted list of all elements that haven't any even digit."""

    result = []
    for num in x:
        if not has_even_digit(num):
            result.append(num)

    return sorted(result)

