def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is a prime number and should return the value of y otherwise."""

    # Check if 'n' is a prime number using the helper function `is_prime`
    if is_prime(n):
        return x  # Return 'x' because 'n' is prime
    else:
        return y  # Return 'y' for non-prime numbers

# Examples usage of the function
print(x_or_y(7, 34, 12))  # Output should be 34 as 7 is a prime number
print(x_or_y(15, 8, 5))   # Output should be 5 because 15 is not a prime number
```
